chart.dataset:
SELECT 'Unit Price' AS series_key, ssol.unit_price_untaxed AS value, sso.created_on AS _date FROM stock_stock_move_line ssol INNER JOIN stock_stock_move sso ON sso.id = ssol.stock_move Inner JOIN studio_app_poultry_farming app ON ssol.product = app.chair_chicks WHERE sso.status_select = 3 GROUP BY sso.created_on, ssol.unit_price_untaxed
UNION
SELECT 'Quantity' AS series_key, ssol.real_qty AS value, sso.created_on AS _date FROM stock_stock_move_line ssol INNER JOIN stock_stock_move sso ON sso.id = ssol.stock_move inner JOIN studio_app_poultry_farming app ON ssol.product = app.chair_chicks WHERE sso.status_select = 3 GROUP BY sso.created_on, ssol.real_qty;

SELECT 'Total Amount' AS series_key, SUM(ssol.unit_price_untaxed * ssol.real_qty) AS value, sso.created_on AS _date FROM stock_stock_move_line ssol INNER JOIN stock_stock_move sso ON sso.id = ssol.stock_move INNER JOIN studio_app_poultry_farming app ON ssol.product = app.chair_chicks WHERE sso.status_select = 3 GROUP BY sso.created_on
UNION
SELECT 'Quantity' AS series_key, ssol.real_qty AS value, sso.created_on AS _date FROM stock_stock_move_line ssol INNER JOIN stock_stock_move sso ON sso.id = ssol.stock_move inner JOIN studio_app_poultry_farming app ON ssol.product = app.chair_chicks WHERE sso.status_select = 3 GROUP BY sso.created_on, ssol.real_qty;

SELECT per.reference AS _reference, (per.female_reform_number + per.male_reform_number) AS _value, 'Total chicks' AS series_key FROM pf_elev_reform per WHERE per.destination = 1 AND per.slaughterhouse IS NOT null and per.status = 1 GROUP BY per.reference, _value
UNION
SELECT per.reference AS _reference, CASE WHEN male_average_weight = 0 OR female_average_weight = 0 THEN (male_average_weight + female_average_weight) ELSE (male_average_weight + female_average_weight) / 2 END AS _value, 'Average weight' AS series_key FROM pf_elev_reform per WHERE per.destination = 1 AND per.slaughterhouse IS NOT null and per.status = 1 GROUP BY per.reference, male_average_weight,female_average_weight;

SELECT per.reference AS _reference, (per.female_reform_number + per.male_reform_number) AS _value, 'Total chicks' AS series_key FROM pf_elev_reform per WHERE per.destination = 1 AND per.slaughterhouse IS NOT null and per.status = 1 GROUP BY per.reference,_value
UNION
SELECT per.reference AS _reference, (per.male_average_weight + per.female_average_weight) AS _value, 'Global weight' AS series_key FROM pf_elev_reform per WHERE per.destination = 1 AND per.slaughterhouse IS NOT null and per.status = 1 GROUP BY per.reference, _value;
